/**
 * PasscodeGate.js — A simple passcode wall shown before the dashboard loads.
 *
 * This exists because the dashboard currently only has training/placeholder
 * data behind it (see the on-screen warning below) and isn't ready for
 * general viewing yet. Wrapping <App> in this component in index.js means
 * nothing in App.js — including its data fetch — runs until the passcode
 * has been entered correctly.
 *
 * IMPORTANT — this is NOT real security. React/CRA ships the entire
 * PASSCODE constant below in plain text inside the built JS bundle, so
 * anyone who opens browser dev tools can read it directly out of the
 * source. It only stops casual/accidental visits, e.g. someone finding the
 * link before it's ready to share. Don't use this pattern to protect
 * anything that actually needs to stay private.
 */
import React, { useState } from "react";

// ─── Change this to set/update the preview passcode ───────────────────────────
const PASSCODE = "phiuk";
// NOTE: the passcode is intentionally asked for on every visit — nothing is
// remembered across page loads or sessions (no localStorage/sessionStorage
// involved). If you'd rather unlock once and stay unlocked, that's a
// straightforward re-add — just ask.

// Same design tokens as App.js, kept local so this gate renders identically
// whether or not the rest of the app has loaded yet.
const BG        = "#f3ede3";
const BG_DARK   = "#faf7ef";
const BG_PANEL  = "#f3ede3";
const TEAL      = "#14687c";
const AQUA      = "#0f93a1";
const CORAL     = "#ff6e51";
const TEXT_DARK = "#1e293b";
const TEXT_MID  = "#475569";

/**
 * PasscodeGate — renders its `children` only after the correct passcode has
 * been entered THIS visit. Nothing is persisted, so reloading the page or
 * returning later always shows this gate again. Until unlocked, it renders
 * a standalone landing page carrying the "training data, illustrative only"
 * warning and a passcode form.
 *
 * @param {{ children: React.ReactNode }} props
 */
function PasscodeGate({ children }) {
  const [unlocked, setUnlocked] = useState(false);
  const [value, setValue] = useState("");
  const [error, setError] = useState(false);

  /** Checks the typed value against PASSCODE and unlocks (or shows an error) on submit. */
  const handleSubmit = (e) => {
    e.preventDefault();
    if (value.trim() === PASSCODE) {
      setUnlocked(true);
      setError(false);
    } else {
      setError(true);
    }
  };

  if (unlocked) return children;

  return (
    <div style={{ fontFamily: "Work Sans, sans-serif", minHeight: "100vh", background: BG, color: TEXT_DARK, display: "flex", flexDirection: "column" }}>

      {/* Header banner — matches the dashboard's own header exactly */}
      <div style={{ background: CORAL, padding: "16px 48px", display: "flex", alignItems: "center", gap: 24, flexWrap: "wrap" }}>
        <div style={{ background: BG_DARK, borderRadius: "10px", padding: "6px 12px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 1px 3px rgba(0,0,0,0.12)" }}>
          <img
            src={`${process.env.PUBLIC_URL}/pmh_logo.png`}
            alt="Logo"
            style={{ width: "180px", maxWidth: "200px", height: "auto", display: "block", objectFit: "contain" }}
            onError={(e) => { e.currentTarget.parentElement.style.display = "none"; }}
          />
        </div>
        <p style={{ color: BG_DARK, margin: 0, fontSize: "clamp(20px, 4vw, 30px)", fontWeight: 600, lineHeight: 1.2, flex: 1, minWidth: 180 }}>
          SimPaths Policy Impacts Visualiser
        </p>
      </div>

      {/* Gate card */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: "40px 20px" }}>
        <div style={{ background: BG_DARK, border: `0.5px solid ${BG_PANEL}`, borderRadius: "12px", padding: "40px 44px", maxWidth: "480px", width: "100%", boxSizing: "border-box", boxShadow: "0 2px 8px rgba(0,0,0,0.08)" }}>

          <p style={{ fontSize: "12px", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: AQUA, margin: "0 0 8px" }}>
            Preview access
          </p>
          <h1 style={{ fontSize: "clamp(22px, 3vw, 28px)", fontWeight: 700, color: TEAL, margin: "0 0 16px", letterSpacing: "-0.3px" }}>
            This dashboard is a work in progress
          </h1>

          {/* Same coral warning-callout style used for Limitations & Interpretation on the main dashboard */}
          <div style={{ background: "#fee8e2", border: "1px solid #fed7ca", borderLeft: `4px solid ${CORAL}`, borderRadius: "8px", padding: "14px 18px", marginBottom: "22px" }}>
            <p style={{ margin: 0, fontSize: "13.5px", color: "#e34f32", lineHeight: 1.65 }}>
              The data currently shown is <strong>training data</strong>, manually split into Baseline and Scenario for development purposes. The results are <strong>not meaningful</strong> — this preview is for illustrative purposes only.
            </p>
          </div>

          <p style={{ fontSize: "14px", color: TEXT_MID, lineHeight: 1.7, margin: "0 0 20px" }}>
            Enter the preview passcode below to continue.
          </p>

          <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            <input
              type="password"
              value={value}
              onChange={(e) => { setValue(e.target.value); if (error) setError(false); }}
              placeholder="Passcode"
              autoFocus
              style={{
                padding: "12px 14px", borderRadius: "8px", fontSize: "15px", color: TEXT_DARK,
                border: error ? "1.5px solid #ff6e51" : "1px solid #ddd8ce", background: "#efece4",
                outline: "none", boxSizing: "border-box", fontFamily: "inherit",
              }}
            />
            {error && (
              <p style={{ margin: 0, fontSize: "12.5px", color: CORAL, fontWeight: 500 }}>
                That passcode isn't right — try again.
              </p>
            )}
            <button
              type="submit"
              style={{
                marginTop: "4px", padding: "12px 16px", borderRadius: "8px", border: "none", cursor: "pointer",
                background: TEAL, color: "#fdfdfd", fontWeight: 700, fontSize: "15px", fontFamily: "inherit",
              }}
            >
              Enter Dashboard →
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

export default PasscodeGate;